# Builds build\dinput8.dll (MSVC x64). Usage: .\build.ps1 [-Deploy]
#   -Deploy copies it into the Banished folder (delete <Banished>\dinput8.dll to uninstall).
param([switch]$Deploy)
$ErrorActionPreference = 'Stop'
$root = $PSScriptRoot
. "$root\tools\paths.ps1"  # game folder / Visual Studio: environment, local-paths.txt or auto-detected
$vcvars = Get-VcVars
# the project's GitHub repository (repo.txt, "owner/name"): update check + "get the DLL" texts
$repo = (Get-Content "$root\repo.txt" -TotalCount 1).Trim()
"// generated by build.ps1 from repo.txt`n#define BMP_GITHUB_REPO `"$repo`"`n#define BMP_GITHUB_REPO_W L`"$repo`"" |
    Set-Content "$root\src\repo_gen.h" -Encoding ascii
New-Item -ItemType Directory -Force "$root\build" | Out-Null

$srcs = @(
    "$root\src\proxy.cpp", "$root\src\log.cpp", "$root\src\hooks.cpp", "$root\src\simheap.cpp", "$root\src\autotest.cpp", "$root\src\actionprobe.cpp", "$root\src\simwatch.cpp", "$root\src\commands.cpp", "$root\src\visualstub.cpp", "$root\src\net.cpp",
    "$root\src\steam.cpp", "$root\src\gameload.cpp", "$root\src\overlay.cpp", "$root\src\towns.cpp", "$root\src\tint.cpp", "$root\src\uiscript.cpp", "$root\src\gameui.cpp", "$root\src\gamewin.cpp", "$root\src\mpdialog.cpp", "$root\src\gamedlg.cpp", "$root\src\ingame.cpp", "$root\src\report.cpp", "$root\src\zipwrite.cpp", "$root\src\update.cpp", "$root\src\gamebuild.cpp",
    "$root\third_party\imgui\imgui.cpp", "$root\third_party\imgui\imgui_draw.cpp", "$root\third_party\imgui\imgui_tables.cpp",
    "$root\third_party\imgui\imgui_widgets.cpp", "$root\third_party\imgui\backends\imgui_impl_dx11.cpp",
    "$root\third_party\imgui\backends\imgui_impl_win32.cpp",
    "$root\third_party\minhook\src\hook.c", "$root\third_party\minhook\src\buffer.c",
    "$root\third_party\minhook\src\trampoline.c", "$root\third_party\minhook\src\hde\hde64.c"
) | ForEach-Object { "`"$_`"" }

$cl = "cl /nologo /LD /O2 /MT /EHsc /std:c++17 /W3 /Zi /I`"$root\third_party\minhook\include`" /I`"$root\third_party\imgui`" " +
      "/Fo`"$root\build\\`" /Fd`"$root\build\\`" /Fe`"$root\build\dinput8.dll`" $($srcs -join ' ') " +
      "/link /DEF:`"$root\src\dinput8.def`" /DEBUG /PDB:`"$root\build\dinput8.pdb`" user32.lib ws2_32.lib shell32.lib ole32.lib advapi32.lib d3d11.lib dxgi.lib d3dcompiler.lib imm32.lib dwmapi.lib windowscodecs.lib winhttp.lib"
cmd /c "`"$vcvars`" >nul && $cl"
if ($LASTEXITCODE) { throw "build failed ($LASTEXITCODE)" }

# the relay server for Windows (server\relay\BanishedRelay.cpp, a port of tools\bmp_relay.py)
$clRelay = "cl /nologo /O2 /MT /EHsc /std:c++17 /W3 /Fo`"$root\build\\`" /Fe`"$root\build\BanishedRelay.exe`" " +
           "`"$root\server\relay\BanishedRelay.cpp`" /link ws2_32.lib iphlpapi.lib winhttp.lib"
cmd /c "`"$vcvars`" >nul && $clRelay"
if ($LASTEXITCODE) { throw "relay build failed ($LASTEXITCODE)" }

if ($Deploy) {
    $game = Get-BanishedDir
    Copy-Item "$root\build\dinput8.dll" "$game\dinput8.dll" -Force
    Write-Host "deployed to $game\dinput8.dll"
}
